written_at.fn_text:
export async function createFeedbackAction(
  workspaceSlug: string,
  _prevState: ActionState,
  formData: FormData
): Promise<ActionState> {
  const user = await requireUser();

  const parsed = feedbackSchema.safeParse({
    title: formData.get("title"),
    body: formData.get("body"),
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid input" };
  }

  const workspace = await prisma.workspace.findUnique({ where: { slug: workspaceSlug } });
  if (!workspace) notFound();

  const membership = await prisma.membership.findUnique({
    where: { userId_workspaceId: { userId: user.id, workspaceId: workspace.id } },
  });
  if (!membership) notFound();

  const { title, body } = parsed.data;
  const candidateUrl = extractFirstUrl(body) ?? extractFirstUrl(title);
  const preview = candidateUrl ? await fetchLinkPreview(candidateUrl) : null;

  const feedback = await prisma.feedback.create({
    data: {
      title,
      body,
      workspaceId: workspace.id,
      authorId: user.id,
      linkUrl: preview?.url ?? candidateUrl ?? null,
      linkTitle: preview?.title ?? null,
      linkDescription: preview?.description ?? null,
      linkImage: preview?.image ?? null,
      linkSiteName: preview?.siteName ?? null,
    },
    include: { author: true },
  });

  if (workspace.webhookUrl) {
    await sendFeedbackWebhook(workspace.webhookUrl, workspace.webhookSecret, {
      event: "feedback.created",
      timestamp: new Date().toISOString(),
      workspace: { id: workspace.id, slug: workspace.slug, name: workspace.name },
      feedback: {
        id: feedback.id,
        title: feedback.title,
        body: feedback.body,
        url: `${process.env.APP_URL ?? ""}/w/${workspace.slug}/feedback/${feedback.id}`,
        author: { name: feedback.author.name, email: feedback.author.email },
        linkPreview: preview ? { title: preview.title, url: preview.url } : null,
      },
    }).catch((error) => {
      console.error(`[pulseboard] webhook delivery failed for workspace ${workspace.slug}:`, error);
    });
  }

  revalidatePath(`/w/${workspaceSlug}`);
  return {};
}

