  });
  if (!membership) notFound();

  const { title, body } = parsed.data;
  const candidateUrl = extractFirstUrl(body) ?? extractFirstUrl(title);
  const preview = candidateUrl ? await fetchLinkPreview(candidateUrl) : null;

  const feedback = await prisma.feedback.create({
    data: {
      title,
      body,
      workspaceId: workspace.id,
      authorId: user.id,
      linkUrl: preview?.url ?? candidateUrl ?? null,
      linkTitle: preview?.title ?? null,
      linkDescription: preview?.description ?? null,
      linkImage: preview?.image ?? null,
      linkSiteName: preview?.siteName ?? null,
    },
    include: { author: true },
  });

  if (workspace.webhookUrl) {
    const result = await sendFeedbackWebhook(workspace.webhookUrl, workspace.webhookSecret, {
      event: "feedback.created",
      timestamp: new Date().toISOString(),
      workspace: { id: workspace.id, slug: workspace.slug, name: workspace.name },
      feedback: {
        id: feedback.id,
        title: feedback.title,
        body: feedback.body,
        url: `${process.env.APP_URL ?? ""}/w/${workspace.slug}/feedback/${feedback.id}`,
        author: { name: feedback.author?.name ?? "Unknown", email: feedback.author?.email ?? "" },
        linkPreview: preview ? { title: preview.title, url: preview.url } : null,
      },
    });

    await prisma.webhookDelivery.create({
      data: {
        workspaceId: workspace.id,
        feedbackId: feedback.id,
        feedbackTitle: feedback.title,
        url: workspace.webhookUrl,
        success: result.ok,
        statusCode: result.status ?? null,
        error: result.error ?? (result.ok ? null : `HTTP ${result.status}`),
      },
    });
  }

  revalidatePath(`/w/${workspaceSlug}`);
  return { success: true };
}

