import http from "node:http";
import { once } from "node:events";

const { prisma } = await app("lib/prisma.ts");
const { createFeedbackAction } = await app("lib/actions/feedback.ts");
const { requireUser } = await app("lib/workspace.ts");
const { sendFeedbackWebhook } = await app("lib/webhooks.ts");

// Create a user
const user = await prisma.user.create({
  data: {
    email: "testuser@example.com",
    name: "Test User",
    passwordHash: "hashedpassword",
  },
});

// Create workspace with webhookSecret but initially no webhookUrl
const workspace = await prisma.workspace.create({
  data: {
    name: "Test Workspace",
    slug: "test-workspace",
    webhookSecret: "secret",
    webhookUrl: null,
  },
});

// Create membership for user in workspace
await prisma.membership.create({
  data: {
    userId: user.id,
    workspaceId: workspace.id,
    role: "ADMIN",
  },
});

// Set session to simulate signed-in user
set_session({ user: { id: user.id, email: user.email } });

// Prepare valid FormData for feedback
const formData = new FormData();
formData.set("title", "Test Feedback Title");
formData.set("body", "This is a test feedback body.");

// Provide typical previous state (empty)
const prevState = {};

// Helper function to start a local HTTP server that delays response by given ms
async function startSlowWebhookServer(delayMs) {
  const server = http.createServer((req, res) => {
    setTimeout(() => {
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ ok: true }));
    }, delayMs);
  });
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const address = server.address();
  if (!address || typeof address === "string") {
    throw new Error("Failed to start server");
  }
  const url = `http://127.0.0.1:${address.port}/webhook`;
  return { server, url };
}

