import crypto from "crypto";

const WEBHOOK_TIMEOUT_MS = 5000;

export function signPayload(secret: string, payload: string): string {
  return crypto.createHmac("sha256", secret).update(payload).digest("hex");
}

export interface FeedbackWebhookPayload {
  event: "feedback.created";
  timestamp: string;
  workspace: { id: string; slug: string; name: string };
  feedback: {
    id: string;
    title: string;
    body: string;
    url: string;
    author: { name: string; email: string };
    linkPreview: { title: string | null; url: string } | null;
  };
}

/**
 * Fires the outgoing "new feedback" webhook an admin configured for their
 * workspace. Best-effort: a dead or slow endpoint should never block the
 * feedback submission, so failures are swallowed (and surfaced only via
 * server logs for now).
 */
export async function sendFeedbackWebhook(
  webhookUrl: string,
  webhookSecret: string,
  payload: FeedbackWebhookPayload
): Promise<{ ok: boolean; status?: number; error?: string }> {
  // This stub calls the real implementation to preserve real behaviour
  // but can be replaced by the test to simulate slow webhook.
  const realModule = await import("./webhooks.ts");
  return realModule.sendFeedbackWebhook(webhookUrl, webhookSecret, payload);
}

